__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"FAQ",{enumerable:!0,get:function(){return t}});const t={ru:[{q:'\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 Radar Party?',a:'\u0410\u0444\u0438\u0448\u0430 \u0432\u0435\u0447\u0435\u0440\u0438\u043d\u043e\u043a, \u043a\u043e\u043d\u0446\u0435\u0440\u0442\u043e\u0432, stand-up \u0438 \u043a\u0432\u0435\u0441\u0442\u043e\u0432 \u0432 \u0432\u0430\u0448\u0435\u043c \u0433\u043e\u0440\u043e\u0434\u0435: \u0447\u0442\u043e, \u0433\u0434\u0435 \u0438 \u043a\u043e\u0433\u0434\u0430, \u0446\u0435\u043d\u0430 \u0438 \u0441\u0441\u044b\u043b\u043a\u0430 \u043d\u0430 \u0431\u0438\u043b\u0435\u0442\u044b.'},{q:'\u041a\u0430\u043a \u0441\u043c\u0435\u043d\u0438\u0442\u044c \u0433\u043e\u0440\u043e\u0434?',a:'\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0433\u043e\u0440\u043e\u0434\u0430 \u0432\u0432\u0435\u0440\u0445\u0443 \u0433\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u044d\u043a\u0440\u0430\u043d\u0430 \u0438\u043b\u0438 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u041c\u0435\u043d\u044e \u2192 \u0413\u043e\u0440\u043e\u0434.'},{q:'\u041a\u0430\u043a \u0441\u043c\u0435\u043d\u0438\u0442\u044c \u044f\u0437\u044b\u043a?',a:'\u041c\u0435\u043d\u044e \u2192 \u042f\u0437\u044b\u043a. \u0414\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u049b\u0430\u0437\u0430\u049b\u0448\u0430, \u0440\u0443\u0441\u0441\u043a\u0438\u0439 \u0438 English.'},{q:'\u041a\u0430\u043a \u043a\u0443\u043f\u0438\u0442\u044c \u0431\u0438\u043b\u0435\u0442?',a:'\u041d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041a\u0443\u043f\u0438\u0442\u044c \u0431\u0438\u043b\u0435\u0442\xbb \u2014 \u043e\u0442\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0430, \u043e\u043f\u043b\u0430\u0442\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u0442\u0430\u043c. \u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u0440\u044f\u043c\u043e \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438 (Kaspi, Freedom Pay) \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u043f\u043e\u0437\u0436\u0435.'},{q:'\u041a\u0430\u043a \u043d\u0435 \u043f\u043e\u043f\u0430\u0441\u0442\u044c \u043d\u0430 \u043c\u043e\u0448\u0435\u043d\u043d\u0438\u043a\u043e\u0432?',a:'Radar Party \u043d\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u043f\u043b\u0430\u0442\u0443 \u0437\u0430 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0438 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u0437\u0430 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u044b \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0430\u043c. \u041d\u0435 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442\u0435 \u043f\u0440\u0435\u0434\u043e\u043f\u043b\u0430\u0442\u0443 \u043d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u044b\u043c \u043b\u044e\u0434\u044f\u043c, \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u043d\u0430 \u043b\u0438\u0447\u043d\u0443\u044e \u043a\u0430\u0440\u0442\u0443, \u2014 \u043b\u0443\u0447\u0448\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 \u0438\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u0443\u044e \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0431\u0438\u043b\u0435\u0442\u043e\u0432. \u0418\u0449\u0438\u0442\u0435 \u0437\u043d\u0430\u0447\u043e\u043a \xab\u041f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\xbb: \u0442\u0430\u043a\u0438\u0445 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u043e\u0432 \u043c\u044b \u0437\u043d\u0430\u0435\u043c \u043b\u0438\u0447\u043d\u043e. \u041e\u0431\u043c\u0430\u043d\u0443\u043b\u0438 \u2014 \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041f\u043e\u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c\u0441\u044f\xbb: \u043c\u043e\u0434\u0435\u0440\u0430\u0442\u043e\u0440 \u0440\u0430\u0437\u0431\u0435\u0440\u0451\u0442\u0441\u044f, \u0441\u043d\u0438\u043c\u0435\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u043c\u043e\u0448\u0435\u043d\u043d\u0438\u043a\u0430.'},{q:'\u0427\u0442\u043e \u0437\u043d\u0430\u0447\u0438\u0442 \xab\u042f \u043f\u043e\u0439\u0434\u0443\xbb?',a:'\u0421\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0432 \u041c\u0435\u043d\u044e \u2192 \u041c\u043e\u0438 \u043f\u043b\u0430\u043d\u044b, \u0447\u0442\u043e\u0431\u044b \u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u0442\u044c. \u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437, \u0447\u0442\u043e\u0431\u044b \u0443\u0431\u0440\u0430\u0442\u044c.'},{q:'\u0413\u0434\u0435 \u043c\u043e\u0451 \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435?',a:'\u0412\u043e \u0432\u043a\u043b\u0430\u0434\u043a\u0435 \xab\u041f\u0440\u043e\u0444\u0438\u043b\u044c\xbb. \u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u2014 \u043d\u0430\u0436\u0430\u0442\u044c \u043d\u0430 \u0441\u0435\u0440\u0434\u0435\u0447\u043a\u043e.'},{q:'\u041d\u0443\u0436\u043d\u043e \u043b\u0438 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0432 \u0430\u043a\u043a\u0430\u0443\u043d\u0442?',a:'\u041f\u043e\u043a\u0430 \u043d\u0435\u0442. \u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435 \u0438 \u043f\u043b\u0430\u043d\u044b \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u043e\u043c \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u0438 \u043f\u0440\u043e\u043f\u0430\u0434\u0443\u0442, \u0435\u0441\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435. \u0412\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 Google \u0438 Telegram \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0432 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0445 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f\u0445.'},{q:'\u041a\u0430\u043a \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0441\u0432\u043e\u0451 \u0441\u043e\u0431\u044b\u0442\u0438\u0435?',a:'\u041a\u043d\u043e\u043f\u043a\u0430 \xab+\xbb \u0432\u043d\u0438\u0437\u0443 \u044d\u043a\u0440\u0430\u043d\u0430 \u2192 \xab\u0421\u043e\u0431\u044b\u0442\u0438\u0435\xbb. \u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0444\u043e\u0440\u043c\u0443 \u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u043d\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u2014 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0432 \u041c\u0435\u043d\u044e \u2192 \u041c\u043e\u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f. \u041f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u0432 \u043e\u0431\u0449\u0435\u0439 \u0430\u0444\u0438\u0448\u0435 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u0441\u0435\u0440\u0432\u0435\u0440\u0430.'},{q:'\u041a\u0430\u043a \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0431\u0440\u0435\u043d\u0434?',a:'\xab+\xbb \u2192 \xab\u0411\u0440\u0435\u043d\u0434\xbb: \u043b\u043e\u0433\u043e\u0442\u0438\u043f, \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435, \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f, \u043f\u0430\u0440\u0430 \u0441\u043b\u043e\u0432 \u043e \u0441\u0435\u0431\u0435 \u0438 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u044b (Instagram, Telegram, WhatsApp, \u043f\u043e\u0447\u0442\u0430, \u0441\u0430\u0439\u0442). \u0411\u0440\u0435\u043d\u0434 \u043c\u043e\u0436\u043d\u043e \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u0432 \u0444\u043e\u0440\u043c\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f. \u0412\u0441\u0435 \u0431\u0440\u0435\u043d\u0434\u044b \u2014 \u0432 \u041c\u0435\u043d\u044e \u2192 \u041c\u043e\u0438 \u0431\u0440\u0435\u043d\u0434\u044b.'},{q:'\u041f\u043e\u0447\u0435\u043c\u0443 \u043d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u043d\u0435\u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0435?',a:'\u042d\u0442\u043e \u0442\u0435\u0441\u0442\u043e\u0432\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f: \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u2014 \u043f\u0440\u0438\u043c\u0435\u0440\u044b, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c, \u043a\u0430\u043a \u0432\u0441\u0451 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442. \u041d\u0430\u0441\u0442\u043e\u044f\u0449\u0430\u044f \u0430\u0444\u0438\u0448\u0430 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0430\u043c\u0438.'}],kk:[{q:'Radar Party \u0434\u0435\u0433\u0435\u043d \u043d\u0435?',a:'\u049a\u0430\u043b\u0430\u04a3\u044b\u0437\u0434\u0430\u0493\u044b \u043a\u0435\u0448\u0442\u0435\u0440, \u043a\u043e\u043d\u0446\u0435\u0440\u0442\u0442\u0435\u0440, stand-up \u0436\u04d9\u043d\u0435 \u043a\u0432\u0435\u0441\u0442\u0442\u0435\u0440 \u0430\u0444\u0438\u0448\u0430\u0441\u044b: \u043d\u0435, \u049b\u0430\u0439\u0434\u0430, \u049b\u0430\u0448\u0430\u043d, \u0431\u0430\u0493\u0430\u0441\u044b \u0436\u04d9\u043d\u0435 \u0431\u0438\u043b\u0435\u0442 \u0441\u0456\u043b\u0442\u0435\u043c\u0435\u0441\u0456.'},{q:'\u049a\u0430\u043b\u0430\u043d\u044b \u049b\u0430\u043b\u0430\u0439 \u0430\u0443\u044b\u0441\u0442\u044b\u0440\u0443\u0493\u0430 \u0431\u043e\u043b\u0430\u0434\u044b?',a:'\u0411\u0430\u0441\u0442\u044b \u044d\u043a\u0440\u0430\u043d\u043d\u044b\u04a3 \u0436\u043e\u0493\u0430\u0440\u0493\u044b \u0436\u0430\u0493\u044b\u043d\u0434\u0430\u0493\u044b \u049b\u0430\u043b\u0430 \u0430\u0442\u0430\u0443\u044b\u043d \u0431\u0430\u0441\u044b\u04a3\u044b\u0437 \u043d\u0435\u043c\u0435\u0441\u0435 \u041c\u04d9\u0437\u0456\u0440 \u2192 \u049a\u0430\u043b\u0430 \u0431\u04e9\u043b\u0456\u043c\u0456\u043d \u0430\u0448\u044b\u04a3\u044b\u0437.'},{q:'\u0422\u0456\u043b\u0434\u0456 \u049b\u0430\u043b\u0430\u0439 \u0430\u0443\u044b\u0441\u0442\u044b\u0440\u0443\u0493\u0430 \u0431\u043e\u043b\u0430\u0434\u044b?',a:'\u041c\u04d9\u0437\u0456\u0440 \u2192 \u0422\u0456\u043b. \u049a\u0430\u0437\u0430\u049b\u0448\u0430, \u043e\u0440\u044b\u0441\u0448\u0430 \u0436\u04d9\u043d\u0435 \u0430\u0493\u044b\u043b\u0448\u044b\u043d\u0448\u0430 \u0431\u0430\u0440.'},{q:'\u0411\u0438\u043b\u0435\u0442\u0442\u0456 \u049b\u0430\u043b\u0430\u0439 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0493\u0430 \u0431\u043e\u043b\u0430\u0434\u044b?',a:'\u0406\u0441-\u0448\u0430\u0440\u0430 \u0431\u0435\u0442\u0456\u043d\u0434\u0435 \xab\u0411\u0438\u043b\u0435\u0442 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\xbb \u0442\u04af\u0439\u043c\u0435\u0441\u0456\u043d \u0431\u0430\u0441\u044b\u04a3\u044b\u0437 \u2014 \u04b1\u0439\u044b\u043c\u0434\u0430\u0441\u0442\u044b\u0440\u0443\u0448\u044b\u043d\u044b\u04a3 \u0431\u0435\u0442\u0456 \u0430\u0448\u044b\u043b\u0430\u0434\u044b, \u0442\u04e9\u043b\u0435\u043c \u0441\u043e\u043d\u0434\u0430 \u0436\u0430\u0441\u0430\u043b\u0430\u0434\u044b. \u049a\u043e\u0441\u044b\u043c\u0448\u0430\u043d\u044b\u04a3 \u0456\u0448\u0456\u043d\u0434\u0435 \u0442\u04e9\u043b\u0435\u0443 (Kaspi, Freedom Pay) \u043a\u0435\u0439\u0456\u043d\u0456\u0440\u0435\u043a \u049b\u043e\u0441\u044b\u043b\u0430\u0434\u044b.'},{q:'\u0410\u043b\u0430\u044f\u049b\u0442\u0430\u0440\u0493\u0430 \u049b\u0430\u043b\u0430\u0439 \u0430\u043b\u0434\u0430\u043d\u0431\u0430\u0443\u0493\u0430 \u0431\u043e\u043b\u0430\u0434\u044b?',a:'Radar Party \u0456\u0441-\u0448\u0430\u0440\u0430\u043b\u0430\u0440 \u04af\u0448\u0456\u043d \u0442\u04e9\u043b\u0435\u043c \u049b\u0430\u0431\u044b\u043b\u0434\u0430\u043c\u0430\u0439\u0434\u044b \u0436\u04d9\u043d\u0435 \u04b1\u0439\u044b\u043c\u0434\u0430\u0441\u0442\u044b\u0440\u0443\u0448\u044b\u043b\u0430\u0440\u0493\u0430 \u0430\u0443\u0434\u0430\u0440\u044b\u043c\u0434\u0430\u0440\u0493\u0430 \u0436\u0430\u0443\u0430\u043f \u0431\u0435\u0440\u043c\u0435\u0439\u0434\u0456. \u0411\u0435\u0439\u0442\u0430\u043d\u044b\u0441 \u0430\u0434\u0430\u043c\u0434\u0430\u0440\u0493\u0430, \u04d9\u0441\u0456\u0440\u0435\u0441\u0435 \u0436\u0435\u043a\u0435 \u043a\u0430\u0440\u0442\u0430\u0493\u0430 \u0430\u043b\u0434\u044b\u043d \u0430\u043b\u0430 \u0442\u04e9\u043b\u0435\u043c \u0430\u0443\u0434\u0430\u0440\u043c\u0430\u04a3\u044b\u0437 \u2014 \u043a\u0456\u0440\u0435\u0431\u0435\u0440\u0456\u0441\u0442\u0435 \u043d\u0435\u043c\u0435\u0441\u0435 \u0440\u0435\u0441\u043c\u0438 \u0431\u0438\u043b\u0435\u0442 \u0441\u0430\u0442\u0443 \u0430\u0440\u049b\u044b\u043b\u044b \u0442\u04e9\u043b\u0435\u0433\u0435\u043d \u0434\u04b1\u0440\u044b\u0441. \xab\u0422\u0435\u043a\u0441\u0435\u0440\u0456\u043b\u0433\u0435\u043d \u04b1\u0439\u044b\u043c\u0434\u0430\u0441\u0442\u044b\u0440\u0443\u0448\u044b\xbb \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d \u0456\u0437\u0434\u0435\u04a3\u0456\u0437: \u043c\u04b1\u043d\u0434\u0430\u0439 \u04b1\u0439\u044b\u043c\u0434\u0430\u0441\u0442\u044b\u0440\u0443\u0448\u044b\u043b\u0430\u0440\u0434\u044b \u0431\u0456\u0437 \u0436\u0435\u043a\u0435 \u0431\u0456\u043b\u0435\u043c\u0456\u0437. \u0410\u043b\u0434\u0430\u043d\u044b\u043f \u049b\u0430\u043b\u0441\u0430\u04a3\u044b\u0437 \u2014 \u0456\u0441-\u0448\u0430\u0440\u0430 \u0431\u0435\u0442\u0456\u043d\u0434\u0435 \xab\u0428\u0430\u0493\u044b\u043c\u0434\u0430\u043d\u0443\xbb \u0442\u04af\u0439\u043c\u0435\u0441\u0456\u043d \u0431\u0430\u0441\u044b\u04a3\u044b\u0437: \u043c\u043e\u0434\u0435\u0440\u0430\u0442\u043e\u0440 \u0430\u043d\u044b\u049b\u0442\u0430\u043f, \u0456\u0441-\u0448\u0430\u0440\u0430\u043d\u044b \u0430\u043b\u044b\u043f \u0442\u0430\u0441\u0442\u0430\u0439\u0434\u044b \u0436\u04d9\u043d\u0435 \u0430\u043b\u0430\u044f\u049b\u0442\u044b \u0431\u04b1\u0493\u0430\u0442\u0442\u0430\u0439\u0434\u044b.'},{q:'\xab\u041c\u0435\u043d \u0431\u0430\u0440\u0430\u043c\u044b\u043d\xbb \u043d\u0435\u043d\u0456 \u0431\u0456\u043b\u0434\u0456\u0440\u0435\u0434\u0456?',a:'\u0406\u0441-\u0448\u0430\u0440\u0430 \u0436\u043e\u0493\u0430\u043b\u044b\u043f \u043a\u0435\u0442\u043f\u0435\u0443\u0456 \u04af\u0448\u0456\u043d \u041c\u04d9\u0437\u0456\u0440 \u2192 \u041c\u0435\u043d\u0456\u04a3 \u0436\u043e\u0441\u043f\u0430\u0440\u043b\u0430\u0440\u044b\u043c \u0431\u04e9\u043b\u0456\u043c\u0456\u043d\u0435 \u0442\u04af\u0441\u0435\u0434\u0456. \u0410\u043b\u044b\u043f \u0442\u0430\u0441\u0442\u0430\u0443 \u04af\u0448\u0456\u043d \u049b\u0430\u0439\u0442\u0430 \u0431\u0430\u0441\u044b\u04a3\u044b\u0437.'},{q:'\u0422\u0430\u04a3\u0434\u0430\u0443\u043b\u044b\u043b\u0430\u0440\u044b\u043c \u049b\u0430\u0439\u0434\u0430?',a:'\xab\u041f\u0440\u043e\u0444\u0438\u043b\u044c\xbb \u049b\u043e\u0439\u044b\u043d\u0434\u044b\u0441\u044b\u043d\u0434\u0430. \u0406\u0441-\u0448\u0430\u0440\u0430\u043d\u044b \u049b\u043e\u0441\u0443 \u04af\u0448\u0456\u043d \u0436\u04af\u0440\u0435\u043a\u0448\u0435\u043d\u0456 \u0431\u0430\u0441\u044b\u04a3\u044b\u0437.'},{q:'\u0410\u043a\u043a\u0430\u0443\u043d\u0442\u049b\u0430 \u043a\u0456\u0440\u0443 \u043a\u0435\u0440\u0435\u043a \u043f\u0435?',a:'\u04d8\u0437\u0456\u0440\u0433\u0435 \u0436\u043e\u049b. \u0422\u0430\u04a3\u0434\u0430\u0443\u043b\u044b\u043b\u0430\u0440 \u043c\u0435\u043d \u0436\u043e\u0441\u043f\u0430\u0440\u043b\u0430\u0440 \u043e\u0441\u044b \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0434\u0430 \u0441\u0430\u049b\u0442\u0430\u043b\u0430\u0434\u044b, \u049b\u043e\u0441\u044b\u043c\u0448\u0430\u043d\u044b \u0436\u043e\u0439\u0441\u0430\u04a3\u044b\u0437, \u043e\u043b\u0430\u0440 \u0434\u0430 \u0436\u043e\u0439\u044b\u043b\u0430\u0434\u044b. Google \u0436\u04d9\u043d\u0435 Telegram \u0430\u0440\u049b\u044b\u043b\u044b \u043a\u0456\u0440\u0443 \u043a\u0435\u043b\u0435\u0441\u0456 \u0436\u0430\u04a3\u0430\u0440\u0442\u0443\u043b\u0430\u0440\u0434\u0430 \u049b\u043e\u0441\u044b\u043b\u0430\u0434\u044b.'},{q:'\u04e8\u0437 \u0456\u0441-\u0448\u0430\u0440\u0430\u043c\u0434\u044b \u049b\u0430\u043b\u0430\u0439 \u049b\u043e\u0441\u0430\u043c\u044b\u043d?',a:'\u042d\u043a\u0440\u0430\u043d\u043d\u044b\u04a3 \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u0436\u0430\u0493\u044b\u043d\u0434\u0430\u0493\u044b \xab+\xbb \u0442\u04af\u0439\u043c\u0435\u0441\u0456 \u2192 \xab\u0406\u0441-\u0448\u0430\u0440\u0430\xbb. \u0424\u043e\u0440\u043c\u0430\u043d\u044b \u0442\u043e\u043b\u0442\u044b\u0440\u044b\u043f, \u0442\u0435\u043a\u0441\u0435\u0440\u0443\u0433\u0435 \u0436\u0456\u0431\u0435\u0440\u0456\u04a3\u0456\u0437 \u2014 \u0456\u0441-\u0448\u0430\u0440\u0430 \u041c\u04d9\u0437\u0456\u0440 \u2192 \u041c\u0435\u043d\u0456\u04a3 \u0456\u0441-\u0448\u0430\u0440\u0430\u043b\u0430\u0440\u044b\u043c \u0431\u04e9\u043b\u0456\u043c\u0456\u043d\u0434\u0435 \u043f\u0430\u0439\u0434\u0430 \u0431\u043e\u043b\u0430\u0434\u044b. \u0416\u0430\u043b\u043f\u044b \u0430\u0444\u0438\u0448\u0430\u0434\u0430 \u0436\u0430\u0440\u0438\u044f\u043b\u0430\u0443 \u0441\u0435\u0440\u0432\u0435\u0440 \u049b\u043e\u0441\u044b\u043b\u0493\u0430\u043d\u043d\u0430\u043d \u043a\u0435\u0439\u0456\u043d \u0456\u0441\u043a\u0435 \u049b\u043e\u0441\u044b\u043b\u0430\u0434\u044b.'},{q:'\u0411\u0440\u0435\u043d\u0434\u0442\u0456 \u049b\u0430\u043b\u0430\u0439 \u049b\u04b1\u0440\u0430\u043c\u044b\u043d?',a:'\xab+\xbb \u2192 \xab\u0411\u0440\u0435\u043d\u0434\xbb: \u043b\u043e\u0433\u043e\u0442\u0438\u043f, \u0430\u0442\u0430\u0443\u044b, \u0441\u0430\u043d\u0430\u0442\u044b, \u04e9\u0437\u0456\u04a3\u0456\u0437 \u0442\u0443\u0440\u0430\u043b\u044b \u0431\u0456\u0440\u043d\u0435\u0448\u0435 \u0441\u04e9\u0437 \u0436\u04d9\u043d\u0435 \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0441 (Instagram, Telegram, WhatsApp, \u043f\u043e\u0448\u0442\u0430, \u0441\u0430\u0439\u0442). \u0411\u0440\u0435\u043d\u0434\u0442\u0456 \u0456\u0441-\u0448\u0430\u0440\u0430 \u0444\u043e\u0440\u043c\u0430\u0441\u044b\u043d\u0434\u0430 \u0442\u0430\u04a3\u0434\u0430\u0443\u0493\u0430 \u0431\u043e\u043b\u0430\u0434\u044b. \u0411\u0430\u0440\u043b\u044b\u049b \u0431\u0440\u0435\u043d\u0434\u0442\u0435\u0440 \u2014 \u041c\u04d9\u0437\u0456\u0440 \u2192 \u041c\u0435\u043d\u0456\u04a3 \u0431\u0440\u0435\u043d\u0434\u0442\u0435\u0440\u0456\u043c.'},{q:'\u041d\u0435\u0433\u0435 \u043a\u0435\u0439\u0431\u0456\u0440 \u0456\u0441-\u0448\u0430\u0440\u0430\u043b\u0430\u0440 \u0448\u044b\u043d\u0430\u0439\u044b \u0435\u043c\u0435\u0441?',a:'\u0411\u04b1\u043b \u0442\u0435\u0441\u0442\u0456\u043b\u0456\u043a \u043d\u04b1\u0441\u049b\u0430: \u0456\u0441-\u0448\u0430\u0440\u0430\u043b\u0430\u0440 \u0431\u04d9\u0440\u0456 \u049b\u0430\u043b\u0430\u0439 \u0436\u04b1\u043c\u044b\u0441 \u0456\u0441\u0442\u0435\u0439\u0442\u0456\u043d\u0456\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0443 \u04af\u0448\u0456\u043d \u0431\u0435\u0440\u0456\u043b\u0433\u0435\u043d \u043c\u044b\u0441\u0430\u043b\u0434\u0430\u0440. \u041d\u0430\u0493\u044b\u0437 \u0430\u0444\u0438\u0448\u0430 \u04b1\u0439\u044b\u043c\u0434\u0430\u0441\u0442\u044b\u0440\u0443\u0448\u044b\u043b\u0430\u0440\u043c\u0435\u043d \u0431\u0456\u0440\u0433\u0435 \u043f\u0430\u0439\u0434\u0430 \u0431\u043e\u043b\u0430\u0434\u044b.'}],en:[{q:'What is Radar Party?',a:'A guide to parties, concerts, stand-up and quests in your city: what, where and when, the price and a ticket link.'},{q:'How do I change the city?',a:'Tap the city name at the top of the home screen, or open Menu \u2192 City.'},{q:'How do I change the language?',a:'Menu \u2192 Language. Kazakh, Russian and English are available.'},{q:'How do I buy a ticket?',a:'Tap \u201cBuy ticket\u201d on the event page \u2014 the organizer\u2019s page opens and you pay there. In-app payment (Kaspi, Freedom Pay) is coming later.'},{q:'How do I avoid scammers?',a:'Radar Party does not take payment for events and is not responsible for transfers to organizers. Don\u2019t send prepayments to strangers, especially to a personal card \u2014 pay at the door or through official ticket sales. Look for the \u201cVerified organizer\u201d badge: we know these organizers personally. Got scammed? Tap \u201cReport\u201d on the event page: a moderator will look into it, remove the event and block the scammer.'},{q:'What does \u201cI\u2019m going\u201d do?',a:'The event is saved to Menu \u2192 My plans so you don\u2019t lose it. Tap again to remove it.'},{q:'Where are my favorites?',a:'In the Profile tab. Tap the heart on an event to add it.'},{q:'Do I need an account?',a:'Not yet. Favorites and plans are stored on this phone and will be lost if you delete the app. Sign-in with Google and Telegram is coming in future updates.'},{q:'How do I add my own event?',a:'Tap \u201c+\u201d at the bottom of the screen \u2192 \u201cEvent\u201d. Fill in the form and submit it for review \u2014 the event shows up in Menu \u2192 My events. Publishing to the public listings starts once the server is connected.'},{q:'How do I create a brand?',a:'Tap \u201c+\u201d \u2192 \u201cBrand\u201d: logo, name, category, a few words about you and contacts (Instagram, Telegram, WhatsApp, email, website). You can pick the brand in the event form. All your brands are in Menu \u2192 My brands.'},{q:'Why are some events not real?',a:'This is a beta: the events are samples that show how everything works. The real listings will arrive together with organizers.'}]}},851,[]);